import type { PredictionStrings } from "./predictionsEn";
import { mergePredictions } from "./mergePredictions";

/** Ortak kısa alanlar — tam çeviri nl/pl/cs/da/sv/no/fi/ro/el/hu */
function euroPredictions(
  o: Partial<PredictionStrings>
): PredictionStrings {
  return mergePredictions(o);
}

